package net.officefloor.hq.app.person;

import java.util.List;

/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
 *  the sheet's today, with every grade they have been given (oldest first), and the
 *  version of these values (up by one on each save), and their statements: how many have been taken,
 *  and the last one's due-total and date (both null before the first), and the date they are retired
 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
 *  statement, then count in no live total), and their own terms in days (null when they have none), and their contact (null when they have none), and the sheet they were
 *  transferred from (null when they were not transferred here), and their past retirements (oldest first), and their tags (as {@link net.officefloor.hq.app.claim.Claim#tags(String)} keeps them; null when none). */
public record Person(long id, String name, String grade, long version, long statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
        List<Hold> holds, Integer terms, String contact, String origin,
        List<Retirement> retirements, String tags) {

    public Person withGrades(List<GradeFrom> grades) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags);
    }

    public Person withHolds(List<Hold> holds) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
                !holds.isEmpty(), grades, holds, terms, contact, origin, retirements, tags);
    }

    public Person withRetirements(List<Retirement> retirements) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements, tags);
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Their holds as they act on live totals on the sheet's today: once their retirement date is reached
     *  (the sheet's today on or after it) they are held over every date as well. */
    public List<Hold> liveHolds(String today) {
        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return holds;
        List<Hold> all = new java.util.ArrayList<>(holds);
        all.add(new Hold(null, null));
        return all;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A sheet's people, in list order, and every patron any of them has named, and the ids of
 *  the people the signed-in user watches, and every alias any of them has, and the ids of the people whose name
 *  or an alias is already a name or alias on another sheet of the sheet's tree (read as the store holds it now). */
public record People(List<Person> people, List<Patron> patrons, List<Long> watched, List<Alias> aliases,
        List<Long> clashing) {

    public People withClashing(List<Long> clashing) {
        return new People(people, patrons, watched, aliases, clashing);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val People people, ObjectResponse<People> response) {
        response.send(people);
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPeople {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            PersonRepository repository, PatronRepository patrons, WatchRepository watches, AliasRepository aliases, AsOfView view, Out<People> people) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        people.set(view.read(connection, id, () -> new People(repository.list(id), patrons.list(id), watches.watched(id, by), aliases.list(id), List.of())).withClashing(repository.clashing(id)));
    }
}
-- A person's past retirements: each ran from its from-date (the date they were retired from) to its to-date
-- (the sheet's today when they were unretired). A person may have several over time, kept oldest first (by id).
-- No claim of theirs may be dated after the from-date and before the to-date of any of them.
CREATE TABLE person_retirement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL
